function global:Send-Vis([string]$t,[string]$m){try{$p=New-Object System.IO.Pipes.NamedPipeClientStream(".","PsLastLinePipe",2);$p.Connect(30);$w=New-Object System.IO.StreamWriter($p,(New-Object System.Text.UTF8Encoding($false)));$w.AutoFlush=$true;$w.WriteLine("$PID|$t|$m");$w.Dispose();$p.Dispose();return $true}catch{return $false}}; function global:Get-VisLine{try{$raw=$Host.UI.RawUI;$w=$raw.BufferSize.Width;$y=$raw.CursorPosition.Y;for($r=$y;$r -ge [Math]::Max(0,$y-15);$r--){$rect=New-Object System.Management.Automation.Host.Rectangle(0,$r,($w-1),$r);$l=(($raw.GetBufferContents($rect)|ForEach-Object{$_.Character}) -join "").Trim();if($l.Length -gt 0 -and $l -notmatch "^(\(.+\)\s*)?PS [A-Za-z]:\\" -and $l -notmatch "^vis(\s|$)"){return $l}}}catch{};return $null}; function global:vis([Parameter(ValueFromPipeline=$true)]$in,[switch]$Off){begin{if($Off){$global:VisOn=$false;Write-Host "[vis] Disconnected" -ForegroundColor Yellow;return};$exe="{path}";if(-not([System.IO.Directory]::GetFiles("\\.\pipe\")|Where-Object{$_ -like "*PsLastLinePipe*"}) -and (Test-Path $exe)){Start-Process $exe;Start-Sleep -Milliseconds 400};$buf=@()}process{if(-not $Off -and $null -ne $in){$in;$s=($in|Out-String).Trim();if($s){$buf+=($s -split "\r?\n"|Where-Object{$_.Trim()})}}}end{if($Off){return};if($buf.Count -gt 0){[void](Send-Vis "FOCUS" "");[void](Send-Vis "OUT" $buf[-1].Trim());return};$global:VisOn=$true;if(-not $global:VisHooked){$global:VisHooked=$true;$global:OrigPrompt=$function:prompt;function global:prompt{if($global:VisOn){$last=Get-VisLine;if($last){[void](Send-Vis "OUT" $last)}};& $global:OrigPrompt}};if(Get-Module PSReadLine){Set-PSReadLineKeyHandler -Key Enter -ScriptBlock {if($global:VisOn){[void](Send-Vis "FOCUS" "")};[Microsoft.PowerShell.PSConsoleReadLine]::AcceptLine()}};[void](Send-Vis "FOCUS" "");if(Send-Vis "OUT" "Connected (PID: $PID)"){Write-Host "[vis] Connected (PID: $PID)" -ForegroundColor Green}else{Write-Host "[vis] Can't connect with main.exe" -ForegroundColor Red}}}
